#include <stdio.h>
#include <string.h>

#define MAXV 10

int g[MAXV][MAXV];
int indeg[MAXV];
int q[MAXV];

void topo(int V, const char *name) {
    int front = 0, rear = 0;
    for (int i = 0; i < V; i++)
        if (indeg[i] == 0) q[rear++] = i;

    printf("=== %s ===\n", name);
    printf("初始入度：");
    for (int i = 0; i < V; i++) printf("%d:%d ", i, indeg[i]);
    printf("\n");

    int out = 0;
    printf("拓扑序：");
    while (front < rear) {
        int u = q[front++];
        printf("%d ", u);
        out++;
        for (int v = 0; v < V; v++) {
            if (!g[u][v]) continue;
            indeg[v]--;
            if (indeg[v] == 0) q[rear++] = v;
        }
    }
    printf("\n输出点数 = %d / %d\n", out, V);
    printf("结论：%s\n\n", (out == V) ? "无环，拓扑排序成功" : "输出数 < V，图中存在环，无法拓扑排序");
}

int main(void) {
    int V = 6;

    /* 情形一：DAG */
    memset(g, 0, sizeof(g)); memset(indeg, 0, sizeof(indeg));
    int dag[][2] = {{0,1},{0,2},{1,3},{2,3},{3,4},{2,5}};
    for (int i = 0; i < 6; i++) { g[dag[i][0]][dag[i][1]] = 1; indeg[dag[i][1]]++; }
    topo(V, "情形一：DAG 0->1,0->2,1->3,2->3,3->4,2->5");

    /* 情形二：加入 4->2 造成环 2->3->4->2 */
    memset(g, 0, sizeof(g)); memset(indeg, 0, sizeof(indeg));
    int cyc[][2] = {{0,1},{0,2},{1,3},{2,3},{3,4},{2,5},{4,2}};
    for (int i = 0; i < 7; i++) { g[cyc[i][0]][cyc[i][1]] = 1; indeg[cyc[i][1]]++; }
    topo(V, "情形二：加入 4->2 形成环 2->3->4->2");

    printf("要点：Kahn 法的核心价值是能判环（输出数 < V），且同一层的点可并行处理 ——\n");
    printf("      Makefile / Gradle 任务调度、Maven 依赖解析都是它的实例。\n");
    return 0;
}
